type ctxVersion struct {
	Version int    `json:"version"`
	Reason  string `json:"reason,omitempty"`
}

type ctxChild struct {
	ID      string `json:"id"`
	Version int    `json:"version"`
	Pinned  int    `json:"pinned"`
	Stale   string `json:"stale,omitempty"`
}

